from collections import Counter
import datetime
import warnings
import os
import re
from robot.api import logger
from ta5g_interface_tools import ta5g_interface_tools
from .logger_handler import logger_handler

__all__ = [
    "change_file_extension",
    "change_path_to_file",
    "write_content_to_file",
    "force_to_delimiter",
    "fix_duplicated_names",
    "info_log",
    "time_it",
    "add_sufix_to_file_name",
    "callback_with_params",
    "args_to_table",
    "path_to_import_notation",
]


def multi_isinstance(*tuples_to_check):
    for item in ta5g_interface_tools.force_list(*tuples_to_check):
        if not isinstance(item[0], item[1]):
            raise TypeError('Value: {} is {} type but {} was expected' ''.format(item[0], type(item[0]), item[1]))


def change_file_extension(file_path, ext):
    multi_isinstance([(file_path, str), (ext, str)])
    return os.path.splitext(file_path)[0] + '.' + ext


def change_path_to_file(old_path, new_path=None):
    if not isinstance(old_path, str):
        raise TypeError('Value: old_path is \'{}\' type but \'str\' was expected' ''.format(type(old_path)))
    if not new_path:
        return old_path
    return os.path.join(new_path, os.path.basename(old_path))


def write_content_to_file(content, file_path, flag='w+'):
    with open(file_path, flag) as file_:
        file_.write(content)


def force_to_delimiter(text, delimiter='_'):
    text = _split_camel_case(text, delimiter)
    text = _split_letter_with_digit(text, delimiter)
    text = _split_digit_with_letter(text, delimiter)
    text = _remove_special_characters_from_borders(text)
    text = _change_any_char_except_character_digit_or_underscore(text, delimiter)
    return text.lower()


def _split_camel_case(text, delimiter):
    text = re.sub('([a-z])([A-Z])', r'\1{}\2'.format(delimiter), text)
    return re.sub('([A-Z])([A-Z][a-z])', r'\1{}\2'.format(delimiter), text)


def _split_letter_with_digit(text, delimiter):
    return re.sub('([a-z]|[A-Z])(\\d)', r'\1{}\2'.format(delimiter), text)


def _split_digit_with_letter(text, delimiter):
    return re.sub('(\\d)([a-z]|[A-Z])', r'\1{}\2'.format(delimiter), text)


def _remove_special_characters_from_borders(text):
    removed_left = re.sub('^(\\W+)(\\b\\w+)', r'\2', text)
    return re.sub('(\\b\\w+)(\\W+)$', r'\1', removed_left)


def _change_any_char_except_character_digit_or_underscore(text, delimiter):
    return re.sub('(\\W+)(\\b\\w+)', r'{}\2'.format(delimiter), text)


def fix_duplicated_names(names):
    edited_names = names
    if isinstance(edited_names, tuple):
        edited_names = list(edited_names)
    if isinstance(edited_names, list):
        counts = Counter(edited_names)
        for name, num in list(counts.items()):
            if num > 1:
                for suffix in range(1, num + 1):
                    edited_names[edited_names.index(name)] = name + '_' + str(suffix)
    return edited_names


def info_log(start_log, end_log, level='INFO', **log_kwargs):
    def _info_log(func):
        def wrapper(*args, **kwargs):
            logger_handler(start_log, level, **log_kwargs)
            result = func(*args, **kwargs)
            logger_handler(end_log, level, **log_kwargs)
            return result

        return wrapper

    return _info_log


def time_it(func):
    def timed(*args, **kw):
        func_name_with_args_kwargs = '{}({}{})'.format(func.__name__, args if args else '', kw if kw else '')
        logger.info(
            '========= CODE SPEED =========\n' 'function: {}'.format(func_name_with_args_kwargs), also_console=True
        )

        start_time = datetime.datetime.now()
        try:
            result = func(*args, **kw)
        finally:
            end_time = datetime.datetime.now()

        logger.info(
            '========= CODE SPEED =========\n'
            'function: {0}\n'
            'start time: {1}\n'
            'end time: {2}\n'
            'total time: {3} sec\n'
            ''.format(func_name_with_args_kwargs, start_time, end_time, end_time - start_time),
            also_console=True,
        )

        return result

    return timed


def add_sufix_to_file_name(file_path, sufix):
    path, base_name = os.path.splitext(file_path)
    return path + sufix + base_name


def callback_with_params(callback, *args, **kwargs):
    return lambda: callback(*args, **kwargs)


def args_to_table(args, values=2):
    parsed_data = []
    for num in range(0, len(args), values):
        try:
            data_set = args[num:num + values]
            data_set_size = len(data_set)
            assert data_set_size == values
            if data_set_size == 1:
                parsed_data.append(data_set[0])
            else:
                parsed_data.append(data_set)
        except AssertionError:
            warnings.warn('Data subsets are incomplete or inconsistent')

    return parsed_data


def path_to_import_notation(file_path):
    return file_path.split('.')[0].replace('/', '.').split('robotlte.')[-1]
